theorem_surfaces.type:
have u := FirstOrder.Language.var 0;
have r := FirstOrder.Language.var 1;
have y := FirstOrder.Language.var 2;
have z := FirstOrder.Language.var 3;
have e :=
  { arity := 4, lhs := KFOL.Owner.Term.guarded () (u.step r) y z,
    rhs := (u.step r).step (KFOL.Owner.Term.guarded () r y z) };
Fintype.card KFOL.Owner.BasisObstruction.Carrier = 4 ∧
  (∀ (f : KFOL.Equational.Identity (KFOL.Owner.Symbol Unit)),
      f.variableCount ≤ 3 → f.Holds KFOL.Owner.Four → f.Holds KFOL.Owner.BasisObstruction.Carrier) ∧
    e.Holds KFOL.Owner.Four ∧
      ¬e.Holds KFOL.Owner.BasisObstruction.Carrier ∧
        e.variableCount = 4 ∧
          ∀ (T : KFOL.Equational.Theory (KFOL.Owner.Symbol Unit)) (n : ℕ),
            KFOL.Equational.IsBasis KFOL.Owner.Four T → (∀ f ∈ T, f.variableCount ≤ n) → 4 ≤ n

∀ {Role : Type u} {Var : Type v} (three : Fin 3 ↪ Role) (s t : KFOL.Reset.Term Var),
  have x := FirstOrder.Language.var 0;
  have y := FirstOrder.Language.var 1;
  have z := FirstOrder.Language.var 2;
  have ax := fun i =>
    if i = 0 then { arity := 3, lhs := x.step x, rhs := x }
    else
      if i = 1 then { arity := 3, lhs := (x.step y).step x, rhs := y.step x }
      else
        if i = 2 then { arity := 3, lhs := (x.step y).step y, rhs := x.step y }
        else
          if i = 3 then { arity := 3, lhs := x.step ((x.step y).step z), rhs := x.step (y.step z) }
          else
            if i = 4 then { arity := 3, lhs := ((x.step y).step z).step y, rhs := (x.step z).step y }
            else { arity := 3, lhs := x.step (y.step z), rhs := y.step (x.step z) };
  ((∀ (valuation : Var → KFOL.WinnerSet Role), s.eval valuation = t.eval valuation) ↔
      KFOL.Equational.Derives (Set.range ax) s t) ∧
    Nat.card ↑(Set.range ax) = 6

have x := KFOL.Reset.structureOf fun i j => if j = 0 then 0 else max i j;
Cslib.Complexity.coNPComplete Turing.MultiTapeTM.encBits
  {word |
    ∃ equation,
      KFOL.Circuit.Code.encode KFOL.Reset.Symbol equation = word ∧
        equation.WellFormed ∧ ∀ (valuation : ℕ → Fin 3), ∃ value, equation.eval valuation = some (value, value)}

